package backoff

import (
	"testing"
	"time"
)

func TestCompiles(t *testing.T) {
	_ = Delay
}

func TestDelay(t *testing.T) {
	const base = 100 * time.Millisecond
	const max = 1 * time.Second

	tests := []struct {
		name    string
		attempt int
		base    time.Duration
		max     time.Duration
		want    time.Duration
	}{
		{"attempt zero", 0, base, max, 0},
		{"attempt negative", -3, base, max, 0},
		{"attempt 1 is base", 1, base, max, 100 * time.Millisecond},
		{"attempt 2 doubles", 2, base, max, 200 * time.Millisecond},
		{"attempt 3 quadruples", 3, base, max, 400 * time.Millisecond},
		{"attempt 4 is 800ms", 4, base, max, 800 * time.Millisecond},
		{"doubling passes max", 5, base, max, max},
		{"far past max", 10, base, max, max},
		{"exactly max reached", 5, 125 * time.Millisecond, max, max},
		{"base equals max", 1, max, max, max},
		{"base above max", 1, 2 * max, max, max},
		{"zero base", 3, 0, max, 0},
		{"negative base", 3, -base, max, 0},
		{"zero max", 3, base, 0, 0},
		{"negative max", 3, base, -max, 0},
		{"huge attempt does not overflow", 200, base, max, max},
		{"max int attempt does not overflow", int(^uint(0) >> 1), base, max, max},
		{"huge base and max", 2, time.Duration(1<<62), time.Duration(1<<63 - 1), time.Duration(1 << 63 - 1)},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Delay(tt.attempt, tt.base, tt.max)
			if got != tt.want {
				t.Errorf("Delay(%d, %v, %v) = %v, want %v", tt.attempt, tt.base, tt.max, got, tt.want)
			}
		})
	}
}

func TestDelayNeverExceedsMax(t *testing.T) {
	const base = 3 * time.Millisecond
	const max = 50 * time.Millisecond

	for attempt := 1; attempt <= 100; attempt++ {
		if got := Delay(attempt, base, max); got > max {
			t.Fatalf("Delay(%d) = %v, exceeds max %v", attempt, got, max)
		}
	}
}

